import {seed,process,reply,cancel,key,reason,date,message} from './domain.mjs';
let state;try{state=JSON.parse(localStorage.getItem('turno-claro-v1'));if(!Array.isArray(state?.appointments)||!state.log)state=null;}catch{}state??={appointments:seed(),log:{}};
let selected='a',filter='all';const $=s=>document.querySelector(s);const labels={pending:'Por confirmar',confirmed:'Confirmada',change:'Solicita cambio',cancelled:'Cancelada'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('turno-claro-v1',JSON.stringify(state));}catch{$('#feedback').textContent='No se pudo guardar en este navegador. Los cambios duran sólo esta sesión.';}}
function render(){const list=state.appointments;$('#stats').innerHTML=[['Citas en agenda',list.filter(a=>a.status!=='cancelled').length],['Recordatorios aceptados',Object.values(state.log).filter(l=>l.status==='sent').length],['Citas confirmadas',list.filter(a=>a.status==='confirmed').length]].map(([s,n])=>`<div class="stat"><span>${s}</span><strong>${n}</strong></div>`).join('');
const shown=list.filter(a=>filter==='all'||a.status===filter);$('#appointments').innerHTML=shown.map(a=>{let l=state.log[key(a)];const detail=reason(a)|| (l?.status==='error'?'Error de envío · puedes reintentar':l?.status==='sent'?'Envío aceptado · simulación':'Listo para recordar');return `<article class="appointment"><div class="row"><div class="person"><span class="avatar">${escape(a.name.split(' ').map(s=>s[0]).join(''))}</span><div><strong>${escape(a.name)}</strong><div class="muted">${escape(date(a))}</div></div></div><span class="badge ${a.status}">${labels[a.status]}</span></div><div class="actions"><span class="muted ${l?.status==='error'?'error':''}">${escape(detail)}</span></div><div class="actions"><button class="quiet" data-view="${a.id}">Ver mensaje</button>${a.status!=='cancelled'?`<button class="quiet" data-cancel="${a.id}">Cancelar cita</button>`:''}${a.fail?`<button class="quiet" data-fix="${a.id}">Resolver fallo simulado</button>`:''}</div></article>`;}).join('')||'<p>No hay citas en este filtro.</p>';
const a=list.find(a=>a.id===selected)||list[0],l=state.log[key(a)];$('#patient').innerHTML=`<div class="bubble">${escape(l?.message||message(a))}</div><p class="muted">${l?'Registro: '+escape(l.at)+' · '+(l.status==='sent'?'aceptado':'fallido'):'Vista previa · todavía no enviado'}</p><div class="response"><button data-reply="confirmed" ${l?.status==='sent'&&a.status!=='cancelled'?'':'disabled'}>Simular: confirmar cita</button><button class="quiet" data-reply="change" ${l?.status==='sent'&&a.status!=='cancelled'?'':'disabled'}>Simular: solicitar cambio</button></div><p class="muted">Estado: ${labels[a.status]}</p>`;
}
$('#process').onclick=()=>{process(state);save();render();$('#feedback').textContent='Ciclo simulado completado. Revisa los estados; no se enviaron mensajes reales.';};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.filter){filter=d.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));}else if(d.view)selected=d.view;else if(d.cancel)cancel(state,d.cancel);else if(d.fix){state.appointments.find(a=>a.id===d.fix).fail=false;$('#feedback').textContent='Fallo resuelto. Procesa los recordatorios para reintentar.';}else if(d.reply){reply(state,selected,d.reply);$('#feedback').textContent='Respuesta simulada registrada.';}else return;save();render();});
$('#reset').onclick=()=>{if(!confirm('¿Reiniciar los datos ficticios y borrar el historial del demo?'))return;state={appointments:seed(),log:{}};selected='a';filter='all';document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.filter==='all'));save();render();$('#feedback').textContent='Demo reiniciado.';};render();
